=== BRIEF ===
/**
 * The manager brief: the one band of the screen that answers, in order,
 * "what am I trying to do tonight", "how close am I", and "what is the one
 * thing I should do right now".
 *
 * The arena already carries every fact this needs — the shift goal, the
 * running tally, the open decision, the live incident, the queue at the
 * door. What it never did was say any of it in one place, so a first-time
 * player had to reconstruct the state of the night from a ticket rail, a
 * star row and a scrolling log. This is a pure projection of the state the
 * scene already has: it invents no numbers and reads no metric the engine
 * does not actually keep.
 *
 * Deliberately thin. An earlier pass put the target sentence, five chips
 * and a full-sentence directive in the same band, which restated the same
 * numbers twice and gave a calm shift as much ink as a failing one. What
 * survives is only what changes a decision: the three conditions that can
 * lose the night, and one short instruction.
 *
 * Deliberately absent: any table-wait figure. The only wait the engine can
 * currently produce is `tableWaitMinutes`, which returns the whole-shift
 * clock rather than a per-table arrival delta, so putting it on screen
 * would claim a metric the data does not support (#304).
 */

export type BriefTone = "ok" | "warn" | "bad";

export interface BriefChip {
  readonly label: string;
  readonly value: string;
  readonly tone: BriefTone;
}

export interface ArenaBrief {
  readonly chips: readonly BriefChip[];
  /** Short tag for the current directive — "DECIDE", "FIX", "STEP 2/4". */
  readonly nowLabel: string;
  /** The current issue and the action that answers it, in one sentence. */
  readonly now: string;
  /** What the last answered decision actually did, kept until the next one. */
=== TOAST ===
export interface OutcomeToastState {
  shownOutcomeId?: string;
  outcomeToast?: {
    headline: string;
    tone: "safe" | "risky" | "neutral";
    startedAt: number;
  };
}

export const OUTCOME_TOAST_MS = 2600;

export interface DecisionOutcomeLike {
  id: string;
  headline: string;
  tone: "safe" | "risky" | "neutral";
}

/**
 * Initializes toast state upon scene construction.
 *
 * If `persisted` state is provided (e.g. across a window resize or size-verification
 * reboot), an active toast is preserved with its original `startedAt` timestamp so
 * that its remaining display time and fade-out animation continue uninterrupted.
 * If the toast has expired, its `shownOutcomeId` is still retained so the outcome
 * is not erroneously resurfaced.
 *
 * If no `persisted` state is provided but `lastOutcome` is present on the initial
 * state, a new toast is initialized for startup display.
 */
export function initOutcomeToastState(
  lastOutcome?: DecisionOutcomeLike,
  persisted?: OutcomeToastState,
  now: number = Date.now(),
  durationMs: number = OUTCOME_TOAST_MS,
): OutcomeToastState {
  if (persisted) {
    let outcomeToast: OutcomeToastState["outcomeToast"] | undefined;
    if (persisted.outcomeToast && now - persisted.outcomeToast.startedAt < durationMs) {
      outcomeToast = persisted.outcomeToast;
    }
    return {
      shownOutcomeId: persisted.shownOutcomeId,
      outcomeToast,
    };
  }
  if (lastOutcome) {
    return {
      shownOutcomeId: lastOutcome.id,
      outcomeToast: {
        headline: lastOutcome.headline,
        tone: lastOutcome.tone,
        startedAt: now,
      },
    };
  }
  return {};
}

/**
 * Updates toast state when a new state arrives (e.g. via `setState`).
 *
 * Only starts a new toast if `lastOutcome` has a new ID that has not yet been shown.
 */
export function updateOutcomeToastState(
  current: OutcomeToastState,
  lastOutcome?: DecisionOutcomeLike,
  now: number = Date.now(),
): OutcomeToastState {
  if (lastOutcome && lastOutcome.id !== current.shownOutcomeId) {
    return {
      shownOutcomeId: lastOutcome.id,
      outcomeToast: {
        headline: lastOutcome.headline,
        tone: lastOutcome.tone,
        startedAt: now,
      },
    };
  }
  return current;
}

