function base(overrides: Partial<BriefInput> = {}): BriefInput {
  return {
    orders: [],
    workers: [{ role: "chef", location: "kitchen" }],
    outcomes: { cash: 0, waste: 0, completed: 0 },
    sim: { started: true, running: true },
    waiting: [],
    goal: { cash: 190, maxWalkouts: 2, unsafeAllowed: 0 },
    staff: { chef: { name: "Mira" }, host: { name: "Vela" }, server: { name: "Kip" } },
    tally: { walkouts: 0, unsafeServed: 0 },
    ...overrides,
  };
}

describe("arenaBrief", () => {
  test("carries only the conditions the night is judged on", () => {
    // Waste is a debrief number and the queue is already drawn at the door;
    // neither earns a chip in a band this small.
    expect(arenaBrief(base()).chips.map((chip) => chip.label)).toEqual(["TAKINGS", "WALKOUTS", "UNVERIFIED"]);
  });

  test("reads the fail conditions against the goal, not against a fixed bar", () => {
    const brief = arenaBrief(base({ tally: { walkouts: 2, unsafeServed: 1 }, outcomes: { cash: 200, waste: 0, completed: 9 } }));
    const byLabel = new Map(brief.chips.map((chip) => [chip.label, chip]));
    expect(byLabel.get("TAKINGS")).toEqual({ label: "TAKINGS", value: "$200/$190", tone: "ok" });
    // Progress, not a fail condition: short of target is not an alarm.
    expect(arenaBrief(base()).chips[0]).toEqual({ label: "TAKINGS", value: "$0/$190", tone: "ok" });
===
  }
  if (input.emergency?.active) {
    return { label: "FIX", text: `${input.emergency.kind.replace(/_/g, " ")} — click the oven.` };
  }
  const allergy = input.orders.find((order) => order.allergy && ACTIVE.has(order.status));
  if (allergy) {
    return { label: "SAFETY", text: `Allergy on ${tableLabel(allergy)} — press V to verify.` };
  }
  const queue = input.waiting?.length ?? 0;
  if (queue >= 3 && !input.seatingHeld) {
    return { label: "DOOR", text: `${queue} parties waiting — HOLD the door (H), or let ${name(input, "host", "the host")} seat them.` };
  }
  const ready = input.orders.filter((order) => order.status === "ready").length;
  if (ready > 0) {
    return { label: "PASS", text: `${ready} plate${ready === 1 ? "" : "s"} up — ${name(input, "server", "the server")} runs them from the floor.` };
  }
  const chef = input.workers.find((worker) => worker.role === "chef");
  if (chef && chef.location !== "kitchen") {
    return { label: "STAFF", text: `Drag ${name(input, "chef", "the chef")} onto the kitchen.` };
  }
  return { label: "STEADY", text: "Room is steady — click a ticket to rush it." };
}

export function arenaBrief(input: BriefInput): ArenaBrief {
  const now = directive(input);
  return {
    chips: chips(input),
    nowLabel: now.label,
    now: now.text,
    ...(input.lastOutcome ? { last: input.lastOutcome.headline } : {}),
  };
}
