/**
 * Where every part of the restaurant goes, for a window of any size.
 *
 * The arena is drawn on one canvas with no DOM chrome around it (see the
 * `hotspot()` comment in the scene), so this module is the whole responsive
 * story: there is no CSS to fall back on. Two things it has to get right that
 * a fixed 520×740 layout never had to:
 *
 * 1. **Growing, not just fitting.** A maximised desktop window is ~3× the
 *    baseline's area. Laying the same 6px paddings and 8px labels out across
 *    it leaves a room drawn for a phone with acres of dead space and text too
 *    small to read from a normal viewing distance, so `scale` grows with the
 *    window and every caller multiplies its font sizes and text offsets by
 *    it. `scale` follows whichever axis is *tighter* (`width/520` vs
 *    `height/740`) so growing one axis alone can never push content off the
 *    other, and it is capped at {@link ARENA_MAX_SCALE} — past that the room
 *    stops reading as a room and starts reading as four enormous slabs.
 * 2. **Staying legible when there is no room to grow.** Below
 *    {@link ARENA_COMPACT_WIDTH}×{@link ARENA_COMPACT_HEIGHT} the layout goes
 *    `compact`: tighter paddings, shorter bands — and `scale` pins to 1 so
 *    compact never *shrinks* type. Small text on a small canvas is the one
 *    combination that is actually unreadable, and a phone-sized window is
 *    exactly where the player is closest to the screen.
 *
 * Every rect is clamped into the box it was asked for, so no caller has to
 * defend itself against a band hanging off the bottom edge at an awkward
 * size. The one deliberate exception is `doorStand`, which keeps its
 * {@link DOOR_STAND_MIN_WIDTH}×{@link DOOR_STAND_MIN_HEIGHT} minimum at
 * every size: it is a click target with two lines of text on it, and a host
 * stand too small to hit or read is worse than one that crowds its zone.
 */

export type ArenaRect = { x: number; y: number; width: number; height: number };
export type ArenaPoint = { x: number; y: number };
export type ArenaLocation = "floor" | "kitchen" | "pass" | "queue";

export interface RestaurantArenaLayout {
  compact: boolean;
  scale: number;
  feedBeside: boolean;
  topBar: ArenaRect;
  brief: ArenaRect;
  kitchen: ArenaRect;
  pass: ArenaRect;
  dining: ArenaRect;
  door: ArenaRect;
  doorStand: ArenaRect;
  waypoints: Record<ArenaLocation, ArenaPoint>;
  /** Y coordinate of the hallway line that runs through the pass zone. */
  spineY: number;
  tickets: ArenaRect;
  feed: ArenaRect;
}

/** The size this layout was authored at: `scale` is exactly 1 here. */
export const ARENA_BASE_WIDTH = 520;
export const ARENA_BASE_HEIGHT = 740;
/** Past this the room reads as slabs rather than a room. */
export const ARENA_MAX_SCALE = 1.9;
/** Under either of these the layout tightens up and stops growing text. */
export const ARENA_COMPACT_WIDTH = 460;
export const ARENA_COMPACT_HEIGHT = 420;
/** From here on there is room for the service log beside the floor. */
export const ARENA_FEED_BESIDE_WIDTH = 600;
/** A host stand smaller than this can't be hit or read — see the file note. */
export const DOOR_STAND_MIN_WIDTH = 56;
export const DOOR_STAND_MIN_HEIGHT = 22;

function clamp(value: number, low: number, high: number): number {
  return Math.min(high, Math.max(low, value));
}

/**
 * A design-size band: `target` at the baseline, grown by `scale`, but never
 * taking more than `share` of the space it sits in. The share is what keeps a
 * short window from spending its whole height on chrome.
 */
function band(target: number, scale: number, available: number, share: number): number {
  return Math.round(Math.min(available * share, target * scale));
}

/** Keeps a rect inside the box it was laid out for, at whole pixels. */
function contain(rect: ArenaRect, width: number, height: number): ArenaRect {
  const x = clamp(Math.round(rect.x), 0, width);
  const y = clamp(Math.round(rect.y), 0, height);
  return {
    x,
    y,
    width: clamp(Math.round(rect.width), 0, width - x),
    height: clamp(Math.round(rect.height), 0, height - y),
  };
}

function centerOf(rect: ArenaRect): ArenaPoint {
  return { x: Math.round(rect.x + rect.width / 2), y: Math.round(rect.y + rect.height / 2) };
}

/**
 * How much bigger than the baseline this window can afford to draw. 1 at (or
 * below) the baseline, capped at {@link ARENA_MAX_SCALE}, and pinned to 1
 * whenever the layout is compact so a small canvas never gets small type.
 */
export function arenaScale(width: number, height: number, compact: boolean): number {
  if (compact) return 1;
  const growth = Math.min(width / ARENA_BASE_WIDTH, height / ARENA_BASE_HEIGHT);
  return clamp(growth, 1, ARENA_MAX_SCALE);
}

export function restaurantArenaLayout(width: number, height: number): RestaurantArenaLayout {
  const w = Math.max(1, Math.floor(width));
  const h = Math.max(1, Math.floor(height));

  const compact = w < ARENA_COMPACT_WIDTH || h < ARENA_COMPACT_HEIGHT;
  const scale = arenaScale(w, h, compact);
  const feedBeside = w >= ARENA_FEED_BESIDE_WIDTH;

  const margin = Math.max(2, Math.min(Math.round((compact ? 5 : 8) * scale), Math.round(Math.min(w, h) * 0.04)));
  const gap = Math.max(2, Math.round((compact ? 4 : 6) * scale));
  const innerWidth = Math.max(1, w - margin * 2);
  const innerHeight = Math.max(1, h - margin * 2);

  const topBarHeight = band(compact ? 30 : 38, scale, innerHeight, 0.16);
  const briefHeight = band(compact ? 26 : 32, scale, innerHeight, 0.14);
  const briefY = margin + topBarHeight + gap;
  const bodyY = briefY + briefHeight + gap;
  /** Everything left under the brief band, feed included. */
  const bodyAvailable = Math.max(1, h - margin - bodyY);

  // The service log goes beside the floor once the window is wide enough for
  // both, and under it otherwise. Beside is much better — it is the one panel
  // that wants height, and stacked it steals the floor's.
  let bodyWidth = innerWidth;
  let feed: ArenaRect;
  if (feedBeside) {
    const feedWidth = Math.round(
      clamp(innerWidth * 0.28, Math.min(innerWidth * 0.5, 180 * scale), innerWidth * 0.42),
    );
    bodyWidth = Math.max(1, innerWidth - feedWidth - gap);
    feed = { x: margin + bodyWidth + gap, y: bodyY, width: feedWidth, height: bodyAvailable };
  } else {
    const feedHeight = Math.round(
      Math.min(bodyAvailable * 0.34, Math.max(bodyAvailable * 0.2, (compact ? 74 : 110) * scale)),
    );
    feed = { x: margin, y: h - margin - feedHeight, width: innerWidth, height: feedHeight };
  }
  const bodyHeight = Math.max(1, feedBeside ? bodyAvailable : feed.y - gap - bodyY);

  const ticketsHeight = band(compact ? 58 : 72, scale, bodyHeight, 0.3);
  const floorHeight = Math.max(1, bodyHeight - ticketsHeight - gap);

  // Kitchen ─ pass ─ dining, left to right, with the pass a narrow strip
  // between the two rooms it joins.
  const passWidth = Math.round(clamp(bodyWidth * 0.07, Math.min(bodyWidth * 0.12, 24 * scale), bodyWidth * 0.16));
  const kitchenWidth = Math.round(clamp(bodyWidth * 0.25, Math.min(bodyWidth * 0.3, 96 * scale), bodyWidth * 0.34));
  const kitchen = { x: margin, y: bodyY, width: kitchenWidth, height: floorHeight };
  const pass = { x: kitchen.x + kitchen.width + gap, y: bodyY, width: passWidth, height: floorHeight };
  const diningX = pass.x + pass.width + gap;
  const diningWidth = Math.max(1, margin + bodyWidth - diningX);

  // The door is a band under the dining room: tall enough for its label plus
  // the host stand, and capped so a tall window doesn't turn a doorway into
  // half the floor.
  const labelHeight = Math.round((compact ? 12 : 14) * scale);
  const minDoorHeight = labelHeight + Math.round(26 * scale);
  const doorHeight = Math.round(
    clamp(floorHeight * 0.28, Math.min(minDoorHeight, floorHeight), Math.max(minDoorHeight, 96 * scale)),
  );
  const diningHeight = Math.max(1, floorHeight - doorHeight - gap);
  const dining = { x: diningX, y: bodyY, width: diningWidth, height: diningHeight };
  const door = contain(
    { x: diningX, y: bodyY + diningHeight + gap, width: diningWidth, height: doorHeight },
    w,
    h,
  );

  // The stand sits a gutter in from the doorway so arriving parties have
  // somewhere to queue to the left of the host.
  const standWidth = Math.max(
    DOOR_STAND_MIN_WIDTH,
    Math.min(Math.round(90 * scale), Math.round(door.width * 0.36)),
  );
  const standHeight = Math.max(
    DOOR_STAND_MIN_HEIGHT,
    Math.min(Math.round(36 * scale), door.height - labelHeight - Math.round(4 * scale)),
  );
  const hostGutter = Math.round(clamp(door.width * 0.1, 8, 40 * scale));
  const doorStand: ArenaRect = {
    x: Math.round(Math.min(door.x + hostGutter, door.x + Math.max(0, door.width - standWidth - 4))),
    y: Math.round(Math.min(door.y + labelHeight, Math.max(door.y, door.y + door.height - standHeight))),
    width: standWidth,
    height: standHeight,
  };

  // The hallway. Staff ride this one line between rooms instead of cutting
  // diagonally through tables (see `corridorPoints` in `staff-walk.ts`), so it
  // has to be a y that is inside the pass *and* clear of the dining tables —
  // low in the dining room, just above the door band.
  const spineMargin = Math.min(pass.height * 0.5, 6 * scale);
  const spineY = Math.round(
    clamp(dining.y + dining.height * 0.72, pass.y + spineMargin, pass.y + pass.height - spineMargin),
  );

  const waypoints: Record<ArenaLocation, ArenaPoint> = {
    kitchen: centerOf(kitchen),
    // On the hallway itself: the pass is a doorway staff pass through, not a
    // room they stand in the middle of.
    pass: { x: Math.round(pass.x + pass.width / 2), y: spineY },
    floor: centerOf(dining),
    queue: centerOf(doorStand),
  };

  return {
    compact,
    scale,
    feedBeside,
    topBar: contain({ x: margin, y: margin, width: innerWidth, height: topBarHeight }, w, h),
    brief: contain({ x: margin, y: briefY, width: innerWidth, height: briefHeight }, w, h),
    kitchen: contain(kitchen, w, h),
    pass: contain(pass, w, h),
    dining: contain(dining, w, h),
    door,
    doorStand,
    waypoints,
    spineY,
    tickets: contain({ x: margin, y: bodyY + floorHeight + gap, width: bodyWidth, height: ticketsHeight }, w, h),
    feed: contain(feed, w, h),
  };
}

