/**
 * Holds repaints back while the player is dragging.
 *
 * The arena repaints from scratch on every state change — `children.removeAll`
 * and a fresh set of game objects — which is fine sixty times a shift and
 * fatal exactly once: mid-drag. The token under the pointer is destroyed and
 * rebuilt at the position the *state* still says the worker is at, so the
 * figure snaps out from under the cursor and Phaser's drag, whose target no
 * longer exists, silently dies. The player is left holding nothing, and the
 * drop that would have reassigned the worker never happens. A shift tick
 * landing at the wrong moment is enough to trigger it, so it is not rare.
 *
 * So: paint requests that arrive during a drag are refused and remembered.
 * Exactly one is remembered no matter how many arrive — a repaint is a full
 * redraw of current state, so replaying it twice would draw the same frame
 * twice — and it is replayed once the drag ends, which is the point where the
 * token is allowed to move again.
 *
 * A resize is the one thing that outranks a drag: the whole game is torn down
 * and booted afresh at the new size (see `mountRestaurantArenaScene`), so the
 * drag is over whether the pointer knows it or not and the pending repaint has
 * already happened by definition. `resize()` therefore drops both, and a
 * stray `dragend` arriving afterwards — from the pointer being released over a
 * canvas that no longer exists — correctly owes nothing.
 */
export class RepaintGate {
  private dragging = false;
  private owed = false;

  /** True while a drag is open (between beginDrag() and endDrag()/resize()). */
  get isDragging(): boolean {
    return this.dragging;
  }

  beginDrag(): void {
    this.dragging = true;
    this.owed = false;
  }

  /**
   * Paints immediately (returns true) unless a drag is open, in which case the
   * paint is held back (returns false) and one repaint becomes owed.
   */
  requestPaint(): boolean {
    if (this.dragging) {
      this.owed = true;
      return false;
    }
    return true;
  }

  /**
   * Ends the drag. Returns whether a repaint was held back during it (and thus
   * needs to be replayed by the caller now).
   */
  endDrag(): boolean {
    const owed = this.owed;
    this.dragging = false;
    this.owed = false;
    return owed;
  }

  /**
   * Drops any open drag and clears anything owed, since the resize itself
   * repaints from scratch.
   */
  resize(): void {
    this.dragging = false;
    this.owed = false;
  }
}

