/**
 * Every repaint that isn't the first one goes through here, so a shift tick
 * arriving while the player is carrying a worker doesn't destroy the token
 * under their cursor. The gate replays the held paint on drop — see
 * `restaurant-arena-repaint-gate.ts` for the failure it prevents.
 */
private requestPaint(): void {
  if (this.repaintGate.requestPaint()) this.paint();
}

/**
 * Told from outside that the canvas is about to be replaced at a new size
 * (see `mountRestaurantArenaScene`). Any drag in flight is over — the
 * pointer will be released over a canvas that no longer exists — and the
 * fresh boot repaints everything anyway, so nothing is owed afterwards.
 */
noteResize(): void {
  this.repaintGate.resize();
}

