private stackedSlot(location: Location, offset: number, layout: RestaurantArenaLayout): ArenaPoint {
  const slot = layout.waypoints[location];
  return { x: slot.x + offset * (layout.compact ? 17 : this.sp(22)), y: slot.y };
}

/**
 * Waypoints for a walk that ends on this particular stacked slot, so two
 * cooks sent to the same station stand beside each other instead of inside
 * each other.
 */
private walkWaypoints(layout: RestaurantArenaLayout, location: Location, slot: ArenaPoint): Record<WalkNode, ArenaPoint> {
  return { ...layout.waypoints, [location]: slot };
}

private drawWorkers(layout: RestaurantArenaLayout): void {
  const compact = layout.compact;
  const offsets = new Map<Location, number>();
  this.staffTokens.clear();
  const present = new Set<Role>();

  for (const worker of this.state.workers) {
    const location = this.visualLocation(worker);
    const offset = offsets.get(location) ?? 0;
    offsets.set(location, offset + 1);
    const slot = this.stackedSlot(location, offset, layout);
    present.add(worker.role);

    // The walker, not the layout, decides where the token is drawn: someone
    // reassigned two ticks ago is still out in the corridor, and this paint
    // has to draw them there rather than at the station they are headed for.
    const walker = this.walker(worker.role, location, slot);
    if (walker.node !== location) {
      walker.setTarget(location, this.walkWaypoints(layout, location, slot), layout.spineY);
    } else if (!walker.walking && !walker.dragging && (walker.x !== slot.x || walker.y !== slot.y)) {
      // Same station, different pixel: the window resized, or someone else
      // left the station and the stack closed up.
      walker.snap(slot, location);
    }

    const token = this.buildAvatar(walker.x, walker.y, worker.role, worker.load, compact);
    token.getByName("figure")?.setScale(walker.facing, 1);
    this.staffTokens.set(worker.role, token);
    const heldHost = worker.role === "host" && Boolean(this.state.seatingHeld) && location === "queue";
    const status = heldHost ? "acting" : (this.workerStatuses.get(worker.role) ?? this.workerStatus(worker));
    this.drawWorkerBadge(token, status, compact, heldHost);
    this.drawSpeechBubble(token, worker.role, compact);
    this.makeDraggable(token, worker.role, walker, layout, location);
  }

  for (const role of [...this.walkers.keys()]) {
    if (!present.has(role)) this.walkers.delete(role);
  }
}

private walker(role: Role, location: Location, slot: ArenaPoint): StaffWalker {
  const existing = this.walkers.get(role);
  if (existing) return existing;
  const fresh = new StaffWalker(location, slot);
  this.walkers.set(role, fresh);
  return fresh;
}

// ── Walking and dragging ─────────────────────────────────────────────

/**
 * Advances every walk. This is the one thing on the floor that animates
 * between repaints rather than being redrawn by one, so it moves the
 * existing tokens instead of asking for a paint — at 4× a repaint per frame
 * would be both wasteful and, mid-drag, held back anyway.
 *
 * Frozen while the shift is paused: a stopped clock that still has staff
 * gliding across it says the pause didn't take.
 */
update(_time: number, delta: number): void {
  if (this.walkers.size === 0) return;
  const speed = this.running ? (this.state.sim?.speed ?? 1) : 0;
  if (speed <= 0) return;

  for (const [role, walker] of this.walkers) {
    const wasWalking = walker.walking;
    if (!walker.step(delta, speed)) continue;
    const token = this.staffTokens.get(role);
    if (!token) continue;
    token.setPosition(walker.x, walker.y);
    token.getByName("figure")?.setScale(walker.facing, 1);
    // Arrived: hand the token back to the idle bob it was holding still for.
    if (wasWalking && !walker.walking) this.startIdleBob(token, walker.y, role);
  }
}

/**
 * Carrying a worker to a station is the game's one direct manipulation, so
 * the token itself is the handle: pick it up, the four zones outline
 * themselves, drop it on one and that worker is reassigned.
 *
 * Repaints are gated for the duration (see `RepaintGate`) because a
 * mid-drag repaint destroys the container Phaser is dragging, which both
 * yanks the figure back to its old station and kills the drop.
 */
private makeDraggable(
  token: Phaser.GameObjects.Container,
  role: Role,
  walker: StaffWalker,
  layout: RestaurantArenaLayout,
  from: Location,
): void {
  const grip = this.sp(30);
  token.setSize(grip, grip * 1.6);
  token.setInteractive({ draggable: true, useHandCursor: true });

  token.on("dragstart", () => {
    this.repaintGate.beginDrag();
    walker.dragging = true;
    // The idle bob fights the pointer for the token's y.
    this.tweens.killTweensOf(token);
    token.setDepth(50);
    this.showDropHints(layout, from);
  });

  token.on("drag", (_pointer: Phaser.Input.Pointer, dragX: number, dragY: number) => {
    token.setPosition(dragX, dragY);
    // Keep the walker on the token: whatever happens next — a drop, a
    // bounce back, a resize — starts from where the player left it.
    walker.x = dragX;
    walker.y = dragY;
    if (Math.abs(dragX - walker.x) > 0.5) walker.facing = dragX > walker.x ? 1 : -1;
  });

  token.on("dragend", () => {
    walker.dragging = false;
    this.clearDropHints();
    const target = this.dropLocation(layout, token.x, token.y);
    const landed = target !== undefined && target !== from;
    // Snap rather than walk: the player just carried them there, so the
    // walk already happened in the most literal sense available.
    walker.snap(landed ? this.freeSlot(layout, target!, role) : this.slotFor(layout, from, role), landed ? target! : from);
    token.setPosition(walker.x, walker.y);
    if (landed) this.onAction(`assign_${role}_${target}`);
    // The reassignment above lands a new state, whose repaint the gate held
    // back while the drag was still open. Release it now, once, so the
    // floor catches up in a single redraw.
    if (this.repaintGate.endDrag()) this.paint();
    else token.setDepth(20);
  });
}

/** Which zone a dropped token landed on, if any. */
private dropLocation(layout: RestaurantArenaLayout, x: number, y: number): Location | undefined {
  const hit = (rect: ArenaRect) =>
    x >= rect.x && x <= rect.x + rect.width && y >= rect.y && y <= rect.y + rect.height;
  // The stand is inside the door zone, so it can't win or lose separately.
  if (hit(layout.door) || hit(layout.doorStand)) return "queue";
  if (hit(layout.kitchen)) return "kitchen";
  if (hit(layout.pass)) return "pass";
  if (hit(layout.dining)) return "floor";
  return undefined;
}

/** The slot `role` occupies at `location` given who else is already there. */
private slotFor(layout: RestaurantArenaLayout, location: Location, role: Role): ArenaPoint {
  let offset = 0;
