  }
  parts.push(this.add.rectangle(-unit * 0.8, -unit * 2.2, unit * 0.6, unit * 0.8, 0x2b2118).setOrigin(0.5));
  parts.push(this.add.rectangle(unit * 0.8, -unit * 2.2, unit * 0.6, unit * 0.8, 0x2b2118).setOrigin(0.5));
  return parts;
}

