84	  const x = clamp(Math.round(rect.x), 0, width);
85	  const y = clamp(Math.round(rect.y), 0, height);
86	  return {
87	    x,
88	    y,
89	    width: clamp(Math.round(rect.width), 0, width - x),
90	    height: clamp(Math.round(rect.height), 0, height - y),
91	  };
92	}
93	
94	function centerOf(rect: ArenaRect): ArenaPoint {
95	  return { x: Math.round(rect.x + rect.width / 2), y: Math.round(rect.y + rect.height / 2) };
96	}
97	
98	/**
99	 * How much bigger than the baseline this window can afford to draw. 1 at (or
100	 * below) the baseline, capped at {@link ARENA_MAX_SCALE}, and pinned to 1
101	 * whenever the layout is compact so a small canvas never gets small type.
102	 */
103	export function arenaScale(width: number, height: number, compact: boolean): number {
104	  if (compact) return 1;
105	  const growth = Math.min(width / ARENA_BASE_WIDTH, height / ARENA_BASE_HEIGHT);
106	  return clamp(growth, 1, ARENA_MAX_SCALE);
107	}
108	
109	export function restaurantArenaLayout(width: number, height: number): RestaurantArenaLayout {
110	  const w = Math.max(1, Math.floor(width));
111	  const h = Math.max(1, Math.floor(height));
112	
113	  const compact = w < ARENA_COMPACT_WIDTH || h < ARENA_COMPACT_HEIGHT;
114	  const scale = arenaScale(w, h, compact);
115	  const feedBeside = w >= ARENA_FEED_BESIDE_WIDTH;
116	
117	  const margin = Math.max(2, Math.min(Math.round((compact ? 5 : 8) * scale), Math.round(Math.min(w, h) * 0.04)));
118	  const gap = Math.max(2, Math.round((compact ? 4 : 6) * scale));
119	  const innerWidth = Math.max(1, w - margin * 2);
120	  const innerHeight = Math.max(1, h - margin * 2);
121	
122	  const topBarHeight = band(compact ? 30 : 38, scale, innerHeight, 0.16);
123	  const briefHeight = band(compact ? 26 : 32, scale, innerHeight, 0.14);
124	  const briefY = margin + topBarHeight + gap;
125	  const bodyY = briefY + briefHeight + gap;
126	  /** Everything left under the brief band, feed included. */
127	  const bodyAvailable = Math.max(1, h - margin - bodyY);
128	
129	  // The service log goes beside the floor once the window is wide enough for
130	  // both, and under it otherwise. Beside is much better — it is the one panel
131	  // that wants height, and stacked it steals the floor's.
132	  let bodyWidth = innerWidth;
133	  let feed: ArenaRect;
134	  if (feedBeside) {
135	    const feedWidth = Math.round(
136	      clamp(innerWidth * 0.28, Math.min(innerWidth * 0.5, 180 * scale), innerWidth * 0.42),
137	    );
138	    bodyWidth = Math.max(1, innerWidth - feedWidth - gap);
139	    feed = { x: margin + bodyWidth + gap, y: bodyY, width: feedWidth, height: bodyAvailable };
140	  } else {
141	    const feedHeight = Math.round(
142	      Math.min(bodyAvailable * 0.34, Math.max(bodyAvailable * 0.2, (compact ? 74 : 110) * scale)),
143	    );
144	    feed = { x: margin, y: h - margin - feedHeight, width: innerWidth, height: feedHeight };
145	  }
146	  const bodyHeight = Math.max(1, feedBeside ? bodyAvailable : feed.y - gap - bodyY);
147	
148	  const ticketsHeight = band(compact ? 58 : 72, scale, bodyHeight, 0.3);
149	  const floorHeight = Math.max(1, bodyHeight - ticketsHeight - gap);
150	
151	  // Kitchen ─ pass ─ dining, left to right, with the pass a narrow strip
152	  // between the two rooms it joins.
153	  const passWidth = Math.round(clamp(bodyWidth * 0.07, Math.min(bodyWidth * 0.12, 24 * scale), bodyWidth * 0.16));
154	  const kitchenWidth = Math.round(clamp(bodyWidth * 0.25, Math.min(bodyWidth * 0.3, 96 * scale), bodyWidth * 0.34));
155	  const kitchen = { x: margin, y: bodyY, width: kitchenWidth, height: floorHeight };
156	  const pass = { x: kitchen.x + kitchen.width + gap, y: bodyY, width: passWidth, height: floorHeight };
157	  const diningX = pass.x + pass.width + gap;
158	  const diningWidth = Math.max(1, margin + bodyWidth - diningX);
159	
160	  // The door is a band under the dining room: tall enough for its label plus
161	  // the host stand, and capped so a tall window doesn't turn a doorway into
162	  // half the floor.
163	  const labelHeight = Math.round((compact ? 12 : 14) * scale);
164	  const minDoorHeight = labelHeight + Math.round(26 * scale);
165	  const doorHeight = Math.round(
166	    clamp(floorHeight * 0.28, Math.min(minDoorHeight, floorHeight), Math.max(minDoorHeight, 96 * scale)),
167	  );
168	  const diningHeight = Math.max(1, floorHeight - doorHeight - gap);
169	  const dining = { x: diningX, y: bodyY, width: diningWidth, height: diningHeight };
170	  const door = contain(
171	    { x: diningX, y: bodyY + diningHeight + gap, width: diningWidth, height: doorHeight },
172	    w,
173	    h,
174	  );
175	
176	  // The stand sits a gutter in from the doorway so arriving parties have
177	  // somewhere to queue to the left of the host.
178	  const standWidth = Math.max(
179	    DOOR_STAND_MIN_WIDTH,
180	    Math.min(Math.round(90 * scale), Math.round(door.width * 0.36)),
181	  );
182	  const standHeight = Math.max(
183	    DOOR_STAND_MIN_HEIGHT,
184	    Math.min(Math.round(36 * scale), door.height - labelHeight - Math.round(4 * scale)),
185	  );
186	  const hostGutter = Math.round(clamp(door.width * 0.1, 8, 40 * scale));
187	  const doorStand: ArenaRect = {
188	    x: Math.round(Math.min(door.x + hostGutter, door.x + Math.max(0, door.width - standWidth - 4))),
189	    y: Math.round(Math.min(door.y + labelHeight, Math.max(door.y, door.y + door.height - standHeight))),
190	    width: standWidth,
191	    height: standHeight,
192	  };
193	
194	  // The hallway. Staff ride this one line between rooms instead of cutting
195	  // diagonally through tables (see `corridorPoints` in `staff-walk.ts`), so it
196	  // has to be a y that is inside the pass *and* clear of the dining tables —
197	  // low in the dining room, just above the door band.
198	  const spineMargin = Math.min(pass.height * 0.5, 6 * scale);
199	  const spineY = Math.round(
200	    clamp(dining.y + dining.height * 0.72, pass.y + spineMargin, pass.y + pass.height - spineMargin),
201	  );
202	
203	  const waypoints: Record<ArenaLocation, ArenaPoint> = {
204	    kitchen: centerOf(kitchen),
205	    // On the hallway itself: the pass is a doorway staff pass through, not a
206	    // room they stand in the middle of.
207	    pass: { x: Math.round(pass.x + pass.width / 2), y: spineY },
208	    floor: centerOf(dining),
209	    queue: centerOf(doorStand),
210	  };
211	
212	  return {
213	    compact,
214	    scale,
215	    feedBeside,
216	    topBar: contain({ x: margin, y: margin, width: innerWidth, height: topBarHeight }, w, h),
217	    brief: contain({ x: margin, y: briefY, width: innerWidth, height: briefHeight }, w, h),
218	    kitchen: contain(kitchen, w, h),
219	    pass: contain(pass, w, h),
220	    dining: contain(dining, w, h),
221	    door,
222	    doorStand,
223	    waypoints,
224	    spineY,
225	    tickets: contain({ x: margin, y: bodyY + floorHeight + gap, width: bodyWidth, height: ticketsHeight }, w, h),
226	    feed: contain(feed, w, h),
227	  };
228	}
