1	/**
2	 * Staff crossing the floor on foot.
3	 *
4	 * Four stations, one hallway: `kitchen ─ pass ─ floor ─ queue`. The pass and
5	 * the dining floor are *through-stations*, not shortcuts around each other, so
6	 * a cook sent to the door walks the kitchen out through the pass, across the
7	 * dining room and up to the host stand — the same route a person in that
8	 * building would have to take. Nothing teleports and nothing walks through a
9	 * wall, which is the whole point: a floor where staff move for a reason is a
10	 * floor the player can reason about, and "the chef is still three rooms away
11	 * from the ticket you just rushed" is information you can only read off a
12	 * body actually travelling.
13	 *
14	 * Motion rides the hallway line rather than the straight line between two
15	 * points ({@link corridorPoints}). A diagonal from the oven to the host stand
16	 * cuts through the middle of the dining room and reads as a ghost drifting
17	 * over the tables; an L along the hallway reads as someone walking.
18	 *
19	 * All of this is deliberately pure and frame-rate independent — pixels per
20	 * second, advanced by an explicit `dtMs` and a simulation `speed` — so pausing
21	 * the shift freezes the room, 4× makes the crew hustle, and none of it depends
22	 * on how often the scene happens to repaint.
23	 */
24	
25	import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";
26	
27	export type WalkNode = ArenaLocation;
28	export type Point = ArenaPoint;
29	
30	/**
31	 * The floor plan as a graph. One hallway, no diagonals between rooms — the
32	 * only way from the kitchen to the queue is through the pass and across the
33	 * dining floor.
34	 */
35	export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
36	  kitchen: ["pass"],
37	  pass: ["kitchen", "floor"],
38	  floor: ["pass", "queue"],
39	  queue: ["floor"],
40	};
41	
42	/** A brisk service walk: fast enough not to be annoying, slow enough to read. */
43	export const WALK_SPEED_PX_PER_SEC = 200;
44	
45	/** Sub-pixel wobble that should count as "same point". */
46	const EPSILON = 0.01;
47	
48	/**
49	 * Shortest station-to-station route, `from` and `to` included. Breadth-first
50	 * over {@link WALK_GRAPH}, so `bfsPath("kitchen", "queue")` is
51	 * `["kitchen", "pass", "floor", "queue"]` — never a shortcut — and
52	 * `bfsPath(n, n)` is `[n]`.
53	 */
54	export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
55	  if (from === to) return [from];
56	  const cameFrom = new Map<WalkNode, WalkNode>();
57	  const seen = new Set<WalkNode>([from]);
58	  const frontier: WalkNode[] = [from];
59	
60	  while (frontier.length > 0) {
61	    const node = frontier.shift()!;
62	    for (const next of WALK_GRAPH[node] ?? []) {
63	      if (seen.has(next)) continue;
64	      seen.add(next);
65	      cameFrom.set(next, node);
66	      if (next === to) {
67	        const path: WalkNode[] = [to];
68	        let cursor: WalkNode = to;
69	        while (cameFrom.has(cursor)) {
70	          cursor = cameFrom.get(cursor)!;
71	          path.unshift(cursor);
72	        }
73	        return path;
74	      }
75	      frontier.push(next);
76	    }
77	  }
78	  // Unreachable while the graph stays one connected hallway; an empty path is
79	  // the honest answer rather than a straight-line fallback that would walk
80	  // someone through a wall.
81	  return [];
82	}
83	
84	function samePoint(a: Point, b: Point): boolean {
85	  return Math.abs(a.x - b.x) < EPSILON && Math.abs(a.y - b.y) < EPSILON;
86	}
87	
88	/**
89	 * The pixel polyline for a walk: starts at `start`, visits each node's
90	 * waypoint in order, and gets between them along the `y = spineY` hallway
91	 * instead of cutting the corner. Every segment is axis-aligned — down (or up)
92	 * to the hallway, along it, then into the destination — and zero-length
93	 * segments are dropped, so a walker already standing on the hallway just walks
94	 * along it.
95	 */
96	export function corridorPoints(
97	  start: Point,
98	  nodes: readonly WalkNode[],
99	  waypoints: Record<WalkNode, Point>,
100	  spineY: number,
101	): Point[] {
102	  const points: Point[] = [{ x: start.x, y: start.y }];
103	  const push = (point: Point) => {
104	    const last = points[points.length - 1]!;
105	    if (samePoint(last, point)) return;
106	    points.push({ x: point.x, y: point.y });
107	  };
108	
109	  for (const node of nodes) {
110	    const target = waypoints[node];
111	    if (!target) continue;
112	    const from = points[points.length - 1]!;
113	    // Already square on to the target: that straight line is a corridor move
114	    // in its own right, no detour to the hallway needed.
115	    if (Math.abs(from.y - target.y) < EPSILON || Math.abs(from.x - target.x) < EPSILON) {
116	      push(target);
117	      continue;
118	    }
119	    push({ x: from.x, y: spineY });
120	    push({ x: target.x, y: spineY });
121	    push(target);
122	  }
123	  return points;
124	}
125	
126	/** How long one straight hop takes at {@link WALK_SPEED_PX_PER_SEC}. */
127	export function hopDurationMs(from: Point, to: Point): number {
128	  const distance = Math.hypot(to.x - from.x, to.y - from.y);
129	  return (distance / WALK_SPEED_PX_PER_SEC) * 1000;
130	}
131	
132	/**
133	 * Eased over each hop rather than the whole route, so a walker leans into
134	 * every leg and settles at each corner instead of gliding through them at a
135	 * constant speed — the difference between a person turning a corner and a
136	 * counter being interpolated.
137	 */
138	function ease(t: number): number {
139	  return t * t * (3 - 2 * t);
140	}
141	
142	/**
143	 * One member of staff, walking. Owns its pixel position and nothing else: the
144	 * scene reads `x`/`y`/`facing` to draw a token and never has to know about
145	 * paths, and the game engine keeps owning where people actually are.
146	 */
147	export class StaffWalker {
148	  x: number;
149	  y: number;
150	  /** 1 facing right, -1 facing left. Set from the leg being walked. */
151	  facing: 1 | -1 = 1;
152	  walking = false;
153	  /** While the player is carrying this token, the pointer owns the position. */
154	  dragging = false;
155	  node: WalkNode;
156	
157	  private path: Point[] = [];
158	  /** Index of the point being walked *away* from. */
159	  private leg = 0;
160	  private legElapsedMs = 0;
161	  private legMs = 0;
162	
163	  constructor(node: WalkNode, slot: Point) {
164	    this.node = node;
165	    this.x = slot.x;
166	    this.y = slot.y;
167	  }
168	
169	  snap(slot: Point, node: WalkNode): void {
170	    this.x = slot.x;
171	    this.y = slot.y;
172	    this.node = node;
173	    this.clearPath();
174	  }
175	
176	  /**
177	   * `node` becomes `target` immediately — the assignment has already happened,
178	   * the walk is just how the body catches up — and the route is planned from
179	   * wherever the walker is standing right now, so re-targeting mid-walk picks
180	   * up from the corridor rather than from the station it left.
181	   */
182	  setTarget(target: WalkNode, waypoints: Record<WalkNode, Point>, spineY: number): void {
183	    const route = corridorPoints({ x: this.x, y: this.y }, bfsPath(this.node, target), waypoints, spineY);
184	    this.node = target;
185	    if (route.length < 2) {
186	      // Already standing on the destination.
187	      this.clearPath();
188	      return;
189	    }
190	    this.path = route;
191	    this.leg = 0;
192	    this.legElapsedMs = 0;
193	    this.legMs = hopDurationMs(route[0]!, route[1]!);
194	    this.walking = true;
195	    this.face(route[0]!, route[1]!);
196	  }
197	
198	  step(dtMs: number, speed: number): boolean {
199	    if (!this.walking || this.dragging) return false;
200	    if (!(dtMs > 0) || !(speed > 0)) return false;
201	
202	    const wasX = this.x;
203	    const wasY = this.y;
204	    // Time left to spend this frame. Leftover carries across corners, so a
205	    // long frame or a 4× clock can cross several legs at once.
206	    let budget = dtMs * speed;
207	
208	    while (budget > 0 && this.walking) {
209	      const from = this.path[this.leg]!;
210	      const to = this.path[this.leg + 1]!;
211	      const remaining = this.legMs - this.legElapsedMs;
212	      if (this.legMs <= 0 || budget >= remaining) {
213	        budget -= Math.max(0, remaining);
214	        this.x = to.x;
215	        this.y = to.y;
216	        this.nextLeg();
217	        continue;
218	      }
219	      this.legElapsedMs += budget;
220	      budget = 0;
221	      const t = ease(this.legElapsedMs / this.legMs);
222	      this.x = from.x + (to.x - from.x) * t;
223	      this.y = from.y + (to.y - from.y) * t;
224	      this.face(from, to);
225	    }
226	
227	    return this.x !== wasX || this.y !== wasY;
228	  }
229	
230	  private nextLeg(): void {
231	    this.leg += 1;
232	    this.legElapsedMs = 0;
233	    if (this.leg >= this.path.length - 1) {
234	      this.clearPath();
235	      return;
236	    }
237	    const from = this.path[this.leg]!;
238	    const to = this.path[this.leg + 1]!;
239	    this.legMs = hopDurationMs(from, to);
240	    this.face(from, to);
241	  }
242	
243	  private clearPath(): void {
244	    this.path = [];
245	    this.leg = 0;
246	    this.legElapsedMs = 0;
247	    this.legMs = 0;
248	    this.walking = false;
249	  }
250	
251	  /** A vertical leg keeps the facing it had: nobody turns to walk sideways. */
252	  private face(from: Point, to: Point): void {
253	    if (Math.abs(to.x - from.x) > 0.5) this.facing = to.x > from.x ? 1 : -1;
254	  }
255	}
