/**
 * Staff crossing the floor on foot.
 *
 * Four stations, one hallway: `kitchen ─ pass ─ floor ─ queue`. The pass and
 * the dining floor are *through-stations*, not shortcuts around each other, so
 * a cook sent to the door walks the kitchen out through the pass, across the
 * dining room and up to the host stand — the same route a person in that
 * building would have to take. Nothing teleports and nothing walks through a
 * wall, which is the whole point: a floor where staff move for a reason is a
 * floor the player can reason about, and "the chef is still three rooms away
 * from the ticket you just rushed" is information you can only read off a
 * body actually travelling.
 *
 * Motion rides the hallway line rather than the straight line between two
 * points ({@link corridorPoints}). A diagonal from the oven to the host stand
 * cuts through the middle of the dining room and reads as a ghost drifting
 * over the tables; an L along the hallway reads as someone walking.
 *
 * All of this is deliberately pure and frame-rate independent — pixels per
 * second, advanced by an explicit `dtMs` and a simulation `speed` — so pausing
 * the shift freezes the room, 4× makes the crew hustle, and none of it depends
 * on how often the scene happens to repaint.
 */

import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";

export type WalkNode = ArenaLocation;
export type Point = ArenaPoint;

/**
 * The floor plan as a graph. One hallway, no diagonals between rooms — the
 * only way from the kitchen to the queue is through the pass and across the
 * dining floor.
 */
export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
  kitchen: ["pass"],
  pass: ["kitchen", "floor"],
  floor: ["pass", "queue"],
  queue: ["floor"],
};

/** A brisk service walk: fast enough not to be annoying, slow enough to read. */
export const WALK_SPEED_PX_PER_SEC = 200;

/** Sub-pixel wobble that should count as "same point". */
const EPSILON = 0.01;

/**
 * Shortest station-to-station route, `from` and `to` included. Breadth-first
 * over {@link WALK_GRAPH}, so `bfsPath("kitchen", "queue")` is
 * `["kitchen", "pass", "floor", "queue"]` — never a shortcut — and
 * `bfsPath(n, n)` is `[n]`.
 */
export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
  if (from === to) return [from];
  const cameFrom = new Map<WalkNode, WalkNode>();
  const seen = new Set<WalkNode>([from]);
  const frontier: WalkNode[] = [from];

  while (frontier.length > 0) {
    const node = frontier.shift()!;
    for (const next of WALK_GRAPH[node] ?? []) {
      if (seen.has(next)) continue;
      seen.add(next);
      cameFrom.set(next, node);
      if (next === to) {
        const path: WalkNode[] = [to];
        let cursor: WalkNode = to;
        while (cameFrom.has(cursor)) {
          cursor = cameFrom.get(cursor)!;
          path.unshift(cursor);
        }
        return path;
      }
      frontier.push(next);
    }
  }
  // Unreachable while the graph stays one connected hallway; an empty path is
  // the honest answer rather than a straight-line fallback that would walk
  // someone through a wall.
  return [];
}

function samePoint(a: Point, b: Point): boolean {
  return Math.abs(a.x - b.x) < EPSILON && Math.abs(a.y - b.y) < EPSILON;
}

/**
 * The pixel polyline for a walk: starts at `start`, visits each node's
 * waypoint in order, and gets between them along the `y = spineY` hallway
 * instead of cutting the corner. Every segment is axis-aligned — down (or up)
 * to the hallway, along it, then into the destination — and zero-length
 * segments are dropped, so a walker already standing on the hallway just walks
 * along it.
 */
export function corridorPoints(
  start: Point,
  nodes: readonly WalkNode[],
  waypoints: Record<WalkNode, Point>,
  spineY: number,
): Point[] {
  const points: Point[] = [{ x: start.x, y: start.y }];
  const push = (point: Point) => {
    const last = points[points.length - 1]!;
    if (samePoint(last, point)) return;
    points.push({ x: point.x, y: point.y });
  };

  for (const node of nodes) {
    const target = waypoints[node];
    if (!target) continue;
    const from = points[points.length - 1]!;
    // Already square on to the target: that straight line is a corridor move
    // in its own right, no detour to the hallway needed.
    if (Math.abs(from.y - target.y) < EPSILON || Math.abs(from.x - target.x) < EPSILON) {
      push(target);
      continue;
    }
    push({ x: from.x, y: spineY });
    push({ x: target.x, y: spineY });
    push(target);
  }
  return points;
}

/** How long one straight hop takes at {@link WALK_SPEED_PX_PER_SEC}. */
export function hopDurationMs(from: Point, to: Point): number {
  const distance = Math.hypot(to.x - from.x, to.y - from.y);
  return (distance / WALK_SPEED_PX_PER_SEC) * 1000;
}

/**
 * Eased over each hop rather than the whole route, so a walker leans into
 * every leg and settles at each corner instead of gliding through them at a
 * constant speed — the difference between a person turning a corner and a
 * counter being interpolated.
 */
function ease(t: number): number {
  return t * t * (3 - 2 * t);
}

/**
 * One member of staff, walking. Owns its pixel position and nothing else: the
 * scene reads `x`/`y`/`facing` to draw a token and never has to know about
 * paths, and the game engine keeps owning where people actually are.
 */
export class StaffWalker {
  x: number;
  y: number;
  /** 1 facing right, -1 facing left. Set from the leg being walked. */
  facing: 1 | -1 = 1;
  walking = false;
  /** While the player is carrying this token, the pointer owns the position. */
  dragging = false;
  node: WalkNode;

  private path: Point[] = [];
  /** Index of the point being walked *away* from. */
  private leg = 0;
  private legElapsedMs = 0;
  private legMs = 0;

  constructor(node: WalkNode, slot: Point) {
    this.node = node;
    this.x = slot.x;
    this.y = slot.y;
  }

  snap(slot: Point, node: WalkNode): void {
    this.x = slot.x;
    this.y = slot.y;
    this.node = node;
    this.clearPath();
  }

  /**
   * `node` becomes `target` immediately — the assignment has already happened,
   * the walk is just how the body catches up — and the route is planned from
   * wherever the walker is standing right now, so re-targeting mid-walk picks
   * up from the corridor rather than from the station it left.
   */
  setTarget(target: WalkNode, waypoints: Record<WalkNode, Point>, spineY: number): void {
    const route = corridorPoints({ x: this.x, y: this.y }, bfsPath(this.node, target), waypoints, spineY);
    this.node = target;
    if (route.length < 2) {
      // Already standing on the destination.
      this.clearPath();
      return;
    }
    this.path = route;
    this.leg = 0;
    this.legElapsedMs = 0;
    this.legMs = hopDurationMs(route[0]!, route[1]!);
    this.walking = true;
    this.face(route[0]!, route[1]!);
  }

  step(dtMs: number, speed: number): boolean {
    if (!this.walking || this.dragging) return false;
    if (!(dtMs > 0) || !(speed > 0)) return false;

    const wasX = this.x;
    const wasY = this.y;
    // Time left to spend this frame. Leftover carries across corners, so a
    // long frame or a 4× clock can cross several legs at once.
    let budget = dtMs * speed;

    while (budget > 0 && this.walking) {
      const from = this.path[this.leg]!;
      const to = this.path[this.leg + 1]!;
      const remaining = this.legMs - this.legElapsedMs;
      if (this.legMs <= 0 || budget >= remaining) {
        budget -= Math.max(0, remaining);
        this.x = to.x;
        this.y = to.y;
        this.nextLeg();
        continue;
      }
      this.legElapsedMs += budget;
      budget = 0;
      const t = ease(this.legElapsedMs / this.legMs);
      this.x = from.x + (to.x - from.x) * t;
      this.y = from.y + (to.y - from.y) * t;
      this.face(from, to);
    }

    return this.x !== wasX || this.y !== wasY;
  }

  private nextLeg(): void {
    this.leg += 1;
    this.legElapsedMs = 0;
    if (this.leg >= this.path.length - 1) {
      this.clearPath();
      return;
    }
    const from = this.path[this.leg]!;
    const to = this.path[this.leg + 1]!;
    this.legMs = hopDurationMs(from, to);
    this.face(from, to);
  }

  private clearPath(): void {
    this.path = [];
    this.leg = 0;
    this.legElapsedMs = 0;
    this.legMs = 0;
    this.walking = false;
  }

  /** A vertical leg keeps the facing it had: nobody turns to walk sideways. */
  private face(from: Point, to: Point): void {
    if (Math.abs(to.x - from.x) > 0.5) this.facing = to.x > from.x ? 1 : -1;
  }
}

