import { describe, expect, test } from "bun:test";
import {
  ARENA_BASE_HEIGHT,
  ARENA_BASE_WIDTH,
  ARENA_COMPACT_HEIGHT,
  ARENA_COMPACT_WIDTH,
  ARENA_FEED_BESIDE_WIDTH,
  ARENA_MAX_SCALE,
  DOOR_STAND_MIN_HEIGHT,
  DOOR_STAND_MIN_WIDTH,
  restaurantArenaLayout,
  type ArenaRect,
  type RestaurantArenaLayout,
} from "./restaurant-arena-layout.js";

const RECT_KEYS = ["topBar", "brief", "kitchen", "pass", "dining", "door", "tickets", "feed"] as const;

/** Every window the arena is actually asked to draw itself into, plus the edges. */
const SIZES: readonly [number, number][] = [
  [ARENA_BASE_WIDTH, ARENA_BASE_HEIGHT],
  [320, 240],
  [360, 640],
  [459, 419],
  [460, 420],
  [520, 400],
  [600, 800],
  [900, 700],
  [1200, 1600],
  [1920, 1080],
  [2560, 1440],
  [140, 120],
];

function rects(layout: RestaurantArenaLayout): [string, ArenaRect][] {
  return RECT_KEYS.map((key) => [key, layout[key]]);
}

function overlaps(a: ArenaRect, b: ArenaRect): boolean {
  return (
    a.x < b.x + b.width && b.x < a.x + a.width && a.y < b.y + b.height && b.y < a.y + a.height
  );
}

describe("restaurantArenaLayout", () => {
  test("every band fits inside the window it was asked for", () => {
    for (const [width, height] of SIZES) {
      const layout = restaurantArenaLayout(width, height);
      for (const [name, rect] of rects(layout)) {
        const where = `${name} at ${width}x${height}`;
        expect(rect.x, where).toBeGreaterThanOrEqual(0);
        expect(rect.y, where).toBeGreaterThanOrEqual(0);
        expect(rect.x + rect.width, where).toBeLessThanOrEqual(width);
        expect(rect.y + rect.height, where).toBeLessThanOrEqual(height);
      }
    }
  });

  test("the rooms are laid out left to right and never sit on each other", () => {
    for (const [width, height] of SIZES) {
      const { kitchen, pass, dining, door, topBar, brief } = restaurantArenaLayout(width, height);
      const where = `${width}x${height}`;
      expect(kitchen.x + kitchen.width, where).toBeLessThanOrEqual(pass.x);
      expect(pass.x + pass.width, where).toBeLessThanOrEqual(dining.x);
      // The door is a band under the dining room, sharing its column.
      expect(dining.y + dining.height, where).toBeLessThanOrEqual(door.y);
      expect(overlaps(topBar, brief), where).toBe(false);
      expect(overlaps(kitchen, dining), where).toBe(false);
      expect(overlaps(dining, door), where).toBe(false);
    }
  });

  test("scale is exactly 1 at the baseline and grows with the tighter axis", () => {
    expect(restaurantArenaLayout(ARENA_BASE_WIDTH, ARENA_BASE_HEIGHT).scale).toBe(1);
    // Twice the width but the same height: height is the binding axis, so the
    // room can't grow — widening one axis alone must never push content off the
    // other.
    expect(restaurantArenaLayout(ARENA_BASE_WIDTH * 2, ARENA_BASE_HEIGHT).scale).toBe(1);
    expect(restaurantArenaLayout(ARENA_BASE_WIDTH * 1.5, ARENA_BASE_HEIGHT * 1.5).scale).toBeCloseTo(1.5, 5);
    expect(restaurantArenaLayout(ARENA_BASE_WIDTH * 1.5, ARENA_BASE_HEIGHT * 3).scale).toBeCloseTo(1.5, 5);
  });

  test("scale never drops below 1 or climbs past the cap", () => {
    for (const [width, height] of SIZES) {
      const { scale } = restaurantArenaLayout(width, height);
      expect(scale, `${width}x${height}`).toBeGreaterThanOrEqual(1);
      expect(scale, `${width}x${height}`).toBeLessThanOrEqual(ARENA_MAX_SCALE);
    }
    expect(restaurantArenaLayout(6000, 9000).scale).toBe(ARENA_MAX_SCALE);
  });

  test("a small canvas goes compact and keeps its type at full size", () => {
    expect(restaurantArenaLayout(ARENA_COMPACT_WIDTH - 1, 800).compact).toBe(true);
    expect(restaurantArenaLayout(800, ARENA_COMPACT_HEIGHT - 1).compact).toBe(true);
    expect(restaurantArenaLayout(ARENA_COMPACT_WIDTH, ARENA_COMPACT_HEIGHT).compact).toBe(false);
    // Small text on a small canvas is the one unreadable combination: compact
    // tightens the bands, it does not shrink the words.
    expect(restaurantArenaLayout(320, 240).scale).toBe(1);
    expect(restaurantArenaLayout(2560, ARENA_COMPACT_HEIGHT - 1).scale).toBe(1);
  });

  test("the feed sits beside the floor once there is width for both", () => {
    expect(restaurantArenaLayout(ARENA_FEED_BESIDE_WIDTH - 1, 900).feedBeside).toBe(false);
    expect(restaurantArenaLayout(ARENA_FEED_BESIDE_WIDTH, 900).feedBeside).toBe(true);

    const beside = restaurantArenaLayout(1200, 900);
    expect(beside.feedBeside).toBe(true);
    // Beside means starting right of the floor, not under it.
    expect(beside.feed.x).toBeGreaterThanOrEqual(beside.dining.x + beside.dining.width);
    expect(beside.feed.y).toBeLessThanOrEqual(beside.dining.y);

    const stacked = restaurantArenaLayout(500, 900);
    expect(stacked.feedBeside).toBe(false);
    expect(stacked.feed.y).toBeGreaterThanOrEqual(stacked.tickets.y + stacked.tickets.height);
    expect(overlaps(stacked.feed, stacked.tickets)).toBe(false);
    expect(overlaps(stacked.feed, stacked.dining)).toBe(false);
  });

  test("the host stand stays hittable and readable at every size", () => {
    for (const [width, height] of SIZES) {
      const { doorStand } = restaurantArenaLayout(width, height);
      expect(doorStand.width, `${width}x${height}`).toBeGreaterThanOrEqual(DOOR_STAND_MIN_WIDTH);
      expect(doorStand.height, `${width}x${height}`).toBeGreaterThanOrEqual(DOOR_STAND_MIN_HEIGHT);
    }
  });

  test("the hallway line runs through the pass zone", () => {
    for (const [width, height] of SIZES) {
      const { pass, spineY } = restaurantArenaLayout(width, height);
      const where = `${width}x${height}`;
      expect(spineY, where).toBeGreaterThanOrEqual(pass.y);
      expect(spineY, where).toBeLessThanOrEqual(pass.y + pass.height);
    }
  });

  test("waypoints stand where the rooms are, with the pass one on the hallway", () => {
    for (const [width, height] of SIZES) {
      const layout = restaurantArenaLayout(width, height);
      const { waypoints, kitchen, dining, doorStand, pass, spineY } = layout;
      const where = `${width}x${height}`;

      expect(waypoints.kitchen.x, where).toBeGreaterThanOrEqual(kitchen.x);
      expect(waypoints.kitchen.x, where).toBeLessThanOrEqual(kitchen.x + kitchen.width);
      // The dining waypoint is the resting slot on the floor.
      expect(waypoints.floor.x, where).toBeGreaterThanOrEqual(dining.x);
      expect(waypoints.floor.x, where).toBeLessThanOrEqual(dining.x + dining.width);
      // The queue waypoint is the host stand itself.
      expect(waypoints.queue.x, where).toBeGreaterThanOrEqual(doorStand.x);
      expect(waypoints.queue.x, where).toBeLessThanOrEqual(doorStand.x + doorStand.width);
      expect(waypoints.queue.y, where).toBeGreaterThanOrEqual(doorStand.y);
      expect(waypoints.queue.y, where).toBeLessThanOrEqual(doorStand.y + doorStand.height);
      // A doorway is walked through, not stood in the middle of.
      expect(waypoints.pass.y, where).toBe(spineY);
      expect(waypoints.pass.x, where).toBeGreaterThanOrEqual(pass.x);
      expect(waypoints.pass.x, where).toBeLessThanOrEqual(pass.x + pass.width);
    }
  });

  test("survives sizes no window would ever be", () => {
    for (const [width, height] of [[0, 0], [-40, -40], [1, 1], [520.7, 740.4]] as const) {
      const layout = restaurantArenaLayout(width, height);
      for (const [name, rect] of rects(layout)) {
        const where = `${name} at ${width}x${height}`;
        expect(Number.isFinite(rect.x) && Number.isFinite(rect.y), where).toBe(true);
        expect(rect.width, where).toBeGreaterThanOrEqual(0);
        expect(rect.height, where).toBeGreaterThanOrEqual(0);
      }
    }
    // A fractional window is the same layout as the whole pixels inside it.
    expect(restaurantArenaLayout(520.7, 740.4)).toEqual(restaurantArenaLayout(520, 740));
  });

  test("the same size always lays out the same way", () => {
    expect(restaurantArenaLayout(900, 700)).toEqual(restaurantArenaLayout(900, 700));
  });
});

