import { describe, expect, test } from "bun:test";
import { restaurantArenaLayout } from "./restaurant-arena-layout.js";
import {
  WALK_GRAPH,
  WALK_SPEED_PX_PER_SEC,
  StaffWalker,
  bfsPath,
  corridorPoints,
  hopDurationMs,
  type Point,
  type WalkNode,
} from "./staff-walk.js";

const NODES: readonly WalkNode[] = ["kitchen", "pass", "floor", "queue"];

/** A hand-made floor plan, so the walking numbers below are exact. */
const WAYPOINTS: Record<WalkNode, Point> = {
  kitchen: { x: 60, y: 200 },
  pass: { x: 140, y: 400 },
  floor: { x: 300, y: 200 },
  queue: { x: 320, y: 520 },
};
const SPINE_Y = 400;

function segments(points: readonly Point[]): [Point, Point][] {
  return points.slice(0, -1).map((point, index) => [point, points[index + 1]!]);
}

describe("WALK_GRAPH", () => {
  test("is one hallway: the kitchen only ever reaches the pass", () => {
    expect(WALK_GRAPH.kitchen).toEqual(["pass"]);
    expect(WALK_GRAPH.queue).toEqual(["floor"]);
    // The pass and the floor are through-stations, so they are the only two
    // with a door on each side.
    expect([...WALK_GRAPH.pass].sort()).toEqual(["floor", "kitchen"]);
    expect([...WALK_GRAPH.floor].sort()).toEqual(["pass", "queue"]);
  });

  test("has no shortcut between the kitchen and the door", () => {
    expect(WALK_GRAPH.kitchen).not.toContain("queue");
    expect(WALK_GRAPH.kitchen).not.toContain("floor");
    expect(WALK_GRAPH.queue).not.toContain("kitchen");
    expect(WALK_GRAPH.queue).not.toContain("pass");
  });

  test("every door opens both ways", () => {
    for (const node of NODES) {
      for (const neighbour of WALK_GRAPH[node]) {
        expect(WALK_GRAPH[neighbour], `${neighbour} -> ${node}`).toContain(node);
      }
    }
  });
});

describe("bfsPath", () => {
  test("the kitchen to the queue always walks the whole hallway", () => {
    expect(bfsPath("kitchen", "queue")).toEqual(["kitchen", "pass", "floor", "queue"]);
    expect(bfsPath("queue", "kitchen")).toEqual(["queue", "floor", "pass", "kitchen"]);
  });

  test("includes both ends, so a route is walkable as-is", () => {
    expect(bfsPath("kitchen", "floor")).toEqual(["kitchen", "pass", "floor"]);
    expect(bfsPath("pass", "queue")).toEqual(["pass", "floor", "queue"]);
  });

  test("standing still is a one-node route", () => {
    for (const node of NODES) expect(bfsPath(node, node)).toEqual([node]);
  });

  test("takes the shortest route between every pair of stations", () => {
    for (const from of NODES) {
      for (const to of NODES) {
        const path = bfsPath(from, to);
        expect(path[0], `${from}->${to}`).toBe(from);
        expect(path[path.length - 1], `${from}->${to}`).toBe(to);
        // Consecutive stations must actually share a door.
        for (let i = 1; i < path.length; i += 1) {
          expect(WALK_GRAPH[path[i - 1]!], `${from}->${to}`).toContain(path[i]!);
        }
        expect(path.length, `${from}->${to}`).toBe(Math.abs(NODES.indexOf(from) - NODES.indexOf(to)) + 1);
      }
    }
  });
});

describe("corridorPoints", () => {
  test("rides the hallway instead of cutting across the room", () => {
    const points = corridorPoints(WAYPOINTS.kitchen, bfsPath("kitchen", "queue"), WAYPOINTS, SPINE_Y);
    expect(points[0]).toEqual(WAYPOINTS.kitchen);
    expect(points[points.length - 1]).toEqual(WAYPOINTS.queue);
    // No diagonal anywhere: every leg is either a step to/from the hallway or a
    // run along it.
    for (const [from, to] of segments(points)) {
      const axisAligned = from.x === to.x || from.y === to.y;
      expect(axisAligned, `${JSON.stringify(from)} -> ${JSON.stringify(to)}`).toBe(true);
    }
    // Getting between two rooms happens on the hallway line, never through the
    // middle of the tables.
    const crossings = segments(points).filter(([from, to]) => from.y === to.y && from.x !== to.x);
    expect(crossings.length).toBeGreaterThan(0);
    for (const [from] of crossings) expect(from.y).toBe(SPINE_Y);
  });

  test("drops zero-length legs, so standing on the target adds no points", () => {
    expect(corridorPoints(WAYPOINTS.pass, ["pass"], WAYPOINTS, SPINE_Y)).toEqual([WAYPOINTS.pass]);
    // Already on the hallway: walk straight along it, no detour.
    const along = corridorPoints({ x: 100, y: SPINE_Y }, ["pass"], WAYPOINTS, SPINE_Y);
    expect(along).toEqual([{ x: 100, y: SPINE_Y }, WAYPOINTS.pass]);
  });

  test("starts wherever the walker is standing, not at the station it belongs to", () => {
    const midDrag = { x: 210, y: 90 };
    const points = corridorPoints(midDrag, bfsPath("floor", "kitchen"), WAYPOINTS, SPINE_Y);
    expect(points[0]).toEqual(midDrag);
    expect(points[points.length - 1]).toEqual(WAYPOINTS.kitchen);
  });

  test("stays inside the window when fed a real layout", () => {
    const layout = restaurantArenaLayout(900, 700);
    const points = corridorPoints(layout.waypoints.kitchen, bfsPath("kitchen", "queue"), layout.waypoints, layout.spineY);
    for (const point of points) {
      expect(point.x).toBeGreaterThanOrEqual(0);
      expect(point.x).toBeLessThanOrEqual(900);
      expect(point.y).toBeGreaterThanOrEqual(0);
      expect(point.y).toBeLessThanOrEqual(700);
    }
  });
});

describe("hopDurationMs", () => {
  test("walks at 200px a second", () => {
    expect(WALK_SPEED_PX_PER_SEC).toBe(200);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 200, y: 0 })).toBe(1000);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 0, y: 100 })).toBe(500);
    expect(hopDurationMs({ x: 10, y: 10 }, { x: 40, y: 50 })).toBe(250);
  });

  test("going nowhere takes no time, and direction doesn't matter", () => {
    expect(hopDurationMs({ x: 7, y: 7 }, { x: 7, y: 7 })).toBe(0);
    expect(hopDurationMs({ x: 200, y: 0 }, { x: 0, y: 0 })).toBe(1000);
  });
});

describe("StaffWalker", () => {
  function walker(node: WalkNode = "kitchen"): StaffWalker {
    return new StaffWalker(node, WAYPOINTS[node]);
  }

  test("starts parked at its slot", () => {
    const staff = walker();
    expect([staff.x, staff.y]).toEqual([60, 200]);
    expect(staff.node).toBe("kitchen");
    expect(staff.walking).toBe(false);
    expect(staff.dragging).toBe(false);
    expect(staff.step(16, 1)).toBe(false);
  });

  test("arrives exactly on the target and stops walking", () => {
    const staff = walker();
    staff.setTarget("pass", WAYPOINTS, SPINE_Y);
    expect(staff.walking).toBe(true);
    // 200px down to the hallway plus 80px along it, at 200px/s.
    expect(staff.step(1400, 1)).toBe(true);
    expect([staff.x, staff.y]).toEqual([140, 400]);
    expect(staff.walking).toBe(false);
    expect(staff.step(100, 1)).toBe(false);
  });

  test("crosses the whole hallway in one long frame without overshooting", () => {
    const staff = walker();
    staff.setTarget("queue", WAYPOINTS, SPINE_Y);
    staff.step(60_000, 1);
    expect([staff.x, staff.y]).toEqual([320, 520]);
    expect(staff.node).toBe("queue");
    expect(staff.walking).toBe(false);
  });

  test("the assignment lands immediately; the walk is the body catching up", () => {
    const staff = walker();
    staff.setTarget("queue", WAYPOINTS, SPINE_Y);
    expect(staff.node).toBe("queue");
    expect([staff.x, staff.y]).toEqual([60, 200]);
  });

  test("eases into each hop rather than starting at full speed", () => {
    const staff = walker();
    staff.setTarget("pass", WAYPOINTS, SPINE_Y);
    staff.step(250, 1);
    // A quarter of the way through the leg's time, but not a quarter of its
    // distance — that difference is the lean-in.
    expect(staff.y).toBeGreaterThan(200);
    expect(staff.y).toBeLessThan(250);

    const half = walker();
    half.setTarget("pass", WAYPOINTS, SPINE_Y);
    half.step(500, 1);
    expect(half.y).toBeCloseTo(300, 5);
  });

  test("the sim clock owns the pace: 2x covers twice the ground, paused covers none", () => {
    const fast = walker();
    const slow = walker();
    fast.setTarget("pass", WAYPOINTS, SPINE_Y);
    slow.setTarget("pass", WAYPOINTS, SPINE_Y);
    fast.step(250, 2);
    slow.step(500, 1);
    expect(fast.y).toBeCloseTo(slow.y, 5);

    const paused = walker();
    paused.setTarget("pass", WAYPOINTS, SPINE_Y);
    expect(paused.step(500, 0)).toBe(false);
    expect([paused.x, paused.y]).toEqual([60, 200]);
    // Still walking, just frozen — unpausing picks the walk back up.
    expect(paused.walking).toBe(true);
    expect(paused.step(1400, 1)).toBe(true);
    expect([paused.x, paused.y]).toEqual([140, 400]);
  });

  test("faces the way it is walking, and holds its facing on a vertical leg", () => {
    const staff = walker();
    staff.setTarget("queue", WAYPOINTS, SPINE_Y);
    // First leg is straight down to the hallway: nobody turns to walk sideways.
    expect(staff.facing).toBe(1);
    staff.step(60_000, 1);
    expect(staff.facing).toBe(1);

    staff.setTarget("kitchen", WAYPOINTS, SPINE_Y);
    expect(staff.facing).toBe(-1);
    staff.step(60_000, 1);
    expect([staff.x, staff.y]).toEqual([60, 200]);
    expect(staff.facing).toBe(-1);
  });

  test("the pointer owns the position while a token is being carried", () => {
    const staff = walker();
    staff.setTarget("pass", WAYPOINTS, SPINE_Y);
    staff.dragging = true;
    expect(staff.step(1400, 1)).toBe(false);
    expect([staff.x, staff.y]).toEqual([60, 200]);
    staff.dragging = false;
    expect(staff.step(1400, 1)).toBe(true);
  });

  test("snap drops the walk and takes the station it was dropped on", () => {
    const staff = walker();
    staff.setTarget("queue", WAYPOINTS, SPINE_Y);
    staff.step(300, 1);
    staff.snap(WAYPOINTS.floor, "floor");
    expect([staff.x, staff.y]).toEqual([300, 200]);
    expect(staff.node).toBe("floor");
    expect(staff.walking).toBe(false);
    expect(staff.step(1000, 1)).toBe(false);
  });

  test("re-targeting mid-walk carries on from the corridor", () => {
    const staff = walker();
    staff.setTarget("queue", WAYPOINTS, SPINE_Y);
    staff.step(1500, 1);
    const [x, y] = [staff.x, staff.y];
    staff.setTarget("kitchen", WAYPOINTS, SPINE_Y);
    expect([staff.x, staff.y]).toEqual([x, y]);
    staff.step(60_000, 1);
    expect([staff.x, staff.y]).toEqual([60, 200]);
    expect(staff.node).toBe("kitchen");
  });

  test("being sent where it already stands is not a walk", () => {
    const staff = walker();
    staff.setTarget("kitchen", WAYPOINTS, SPINE_Y);
    expect(staff.walking).toBe(false);
    expect(staff.step(1000, 1)).toBe(false);
  });

  test("never leaves the hallway on the way to its station", () => {
    const layout = restaurantArenaLayout(1200, 900);
    const staff = new StaffWalker("kitchen", layout.waypoints.kitchen);
    staff.setTarget("queue", layout.waypoints, layout.spineY);
    const seen: Point[] = [];
    for (let frame = 0; frame < 400 && staff.walking; frame += 1) {
      staff.step(16, 1);
      seen.push({ x: staff.x, y: staff.y });
    }
    expect(staff.walking).toBe(false);
    expect(seen[seen.length - 1]).toEqual(layout.waypoints.queue);
    // Frame-by-frame, the body only ever moves along one axis at a time.
    for (const [from, to] of segments([{ x: staff.x, y: staff.y }, ...seen].slice(0, seen.length))) {
      expect(from.x === to.x || from.y === to.y).toBe(true);
    }
  });
});

