    expect(staff.node).toBe("kitchen");
    expect(staff.walking).toBe(false);
    expect(staff.dragging).toBe(false);
    expect(staff.step(16, 1)).toBe(false);
  });

  test("arrives exactly on the target and stops walking", () => {
    const staff = walker();
    staff.setTarget("pass", WAYPOINTS, SPINE_Y);
    expect(staff.walking).toBe(true);
    // 200px down to the hallway plus 80px along it, at 200px/s.
    expect(staff.step(1400, 1)).toBe(true);
    expect([staff.x, staff.y]).toEqual([140, 400]);
    expect(staff.walking).toBe(false);
    expect(staff.step(100, 1)).toBe(false);
  });

  test("crosses the whole hallway in one long frame without overshooting", () => {
    const staff = walker();
    staff.setTarget("queue", WAYPOINTS, SPINE_Y);
    staff.step(60_000, 1);
