    half.setTarget("pass", WAYPOINTS, SPINE_Y);
    half.step(500, 1);
    expect(half.y).toBeCloseTo(300, 5);
  });

  test("the sim clock owns the pace: 2x covers twice the ground, paused covers none", () => {
    const fast = walker();
    const slow = walker();
    fast.setTarget("pass", WAYPOINTS, SPINE_Y);
    slow.setTarget("pass", WAYPOINTS, SPINE_Y);
    fast.step(250, 2);
    slow.step(500, 1);
    expect(fast.y).toBeCloseTo(slow.y, 5);

