    const staff = new StaffWalker("kitchen", layout.waypoints.kitchen);
    staff.setTarget("queue", layout.waypoints, layout.spineY);
    const seen: Point[] = [];
    for (let frame = 0; frame < 400 && staff.walking; frame += 1) {
      staff.step(16, 1);
      seen.push({ x: staff.x, y: staff.y });
    }
    expect(staff.walking).toBe(false);
    expect(seen[seen.length - 1]).toEqual(layout.waypoints.queue);
    // Frame-by-frame, the body only ever moves along one axis at a time.
    for (const [from, to] of segments([{ x: staff.x, y: staff.y }, ...seen].slice(0, seen.length))) {
      expect(from.x === to.x || from.y === to.y).toBe(true);
    }
  });
});

