import { describe, expect, test } from "bun:test";
import { RepaintGate } from "./restaurant-arena-repaint-gate.js";

describe("RepaintGate", () => {
  test("paints straight away when nothing is being dragged", () => {
    const gate = new RepaintGate();
    expect(gate.requestPaint()).toBe(true);
    expect(gate.requestPaint()).toBe(true);
    expect(gate.isDragging).toBe(false);
  });

  test("holds every repaint while a drag is open", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.isDragging).toBe(true);
    // A repaint mid-drag rebuilds the token from state and yanks it out of the
    // player's hand, so the tick, the state update and the status all wait.
    expect(gate.requestPaint()).toBe(false);
    expect(gate.requestPaint()).toBe(false);
    expect(gate.requestPaint()).toBe(false);
  });

  test("owes exactly one repaint no matter how many were held", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    for (let i = 0; i < 20; i += 1) gate.requestPaint();
    expect(gate.endDrag()).toBe(true);
    expect(gate.isDragging).toBe(false);
    // The one owed repaint has been paid: a second dragend owes nothing.
    expect(gate.endDrag()).toBe(false);
  });

  test("owes nothing when the drag held nothing back", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.endDrag()).toBe(false);
  });

  test("paints again immediately once the drag is over", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.endDrag();
    expect(gate.requestPaint()).toBe(true);
  });

  test("a resize drops the drag and clears anything owed", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.resize();
    expect(gate.isDragging).toBe(false);
    // The scene was torn down and rebooted under the pointer; the token the
    // drag belonged to no longer exists, so the stray dragend owes nothing.
    expect(gate.endDrag()).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("a resize with no drag open changes nothing", () => {
    const gate = new RepaintGate();
    gate.resize();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("a fresh drag starts clean rather than inheriting the last one's debt", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.beginDrag();
    expect(gate.endDrag()).toBe(false);
  });

  test("an endDrag out of nowhere owes nothing", () => {
    const gate = new RepaintGate();
    expect(gate.endDrag()).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("walks a whole drag-and-drop the way the scene drives it", () => {
    const gate = new RepaintGate();
    const painted: string[] = [];
    const request = (why: string) => {
      if (gate.requestPaint()) painted.push(why);
    };

    request("state");
    gate.beginDrag();
    request("clock tick");
    request("state: worker reassigned");
    request("status: on the move");
    expect(painted).toEqual(["state"]);
    if (gate.endDrag()) painted.push("after drop");
    expect(painted).toEqual(["state", "after drop"]);
    request("clock tick");
    expect(painted).toEqual(["state", "after drop", "clock tick"]);
  });
});

